<script setup lang="ts">
const { t } = useLanguage()
import { Receipt, Plus } from 'lucide-vue-next'
const supabase=useSupabase(),month=ref(nowMonth()),rows=ref<any[]>([]),loading=ref(false),error=ref(''),success=ref(''),modal=ref(false),saving=ref(false)
const form=reactive({category:'کرایه',description:'',amount:0,spent_on:todayKarachi()})
const total=computed(()=>rows.value.filter(r=>!r.voided_at).reduce((a,r)=>a+Number(r.amount),0))
async function load(){loading.value=true;error.value='';rows.value=[];try{if(!supabase)throw Error('Supabase is not configured');if(!isValidMonth(month.value))throw Error(t('financialUi.finance.monthInvalid'));const start=monthStart(month.value);const [y,m]=month.value.split('-').map(Number);const end=new Date(Date.UTC(y!,m!,1)).toISOString().slice(0,10);const q=await supabase.from('expenses').select('*').gte('spent_on',start).lt('spent_on',end).order('spent_on',{ascending:false});if(q.error)throw q.error;rows.value=q.data||[]}catch(e){error.value=errText(e)}finally{loading.value=false}}
async function save(){if(!supabase)return;saving.value=true;error.value='';try{if(form.amount<=0||!form.description.trim())throw Error(t('financialUi.expenses.amountDescriptionRequired'));const r=await supabase.from('expenses').insert({category:form.category,description:form.description.trim(),amount:form.amount,spent_on:form.spent_on});if(r.error)throw r.error;modal.value=false;success.value=t('financialUi.expenses.saved');form.description='';form.amount=0;await load()}catch(e:any){error.value=errText(e)}finally{saving.value=false}}
async function voidExpense(row:any){if(!supabase||saving.value)return;const reason=window.prompt(t('financialUi.expenses.voidPrompt'));if(!reason)return;saving.value=true;try{const q=await supabase.rpc('void_expense',{p_id:row.id,p_reason:reason});if(q.error)throw q.error;await load()}catch(e){error.value=errText(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><PageTitle :title="t('financialUi.expenses.title')" :subtitle="t('financialUi.expenses.subtitle')"><button class="btn primary" @click="modal=true"><Plus :size="17"/> {{ t('financialUi.expenses.new') }}</button></PageTitle><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><section class="card"><div class="table-toolbar"><label>{{ t('financialUi.month') }}<input v-model="month" type="month" @change="load"/></label><span v-if="!loading&&!error" class="badge info">{{ t('financialUi.expenses.total') }} {{money(total)}}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.date') }}</th><th>{{ t('financialUi.partners.edit') }}</th><th>{{ t('financialUi.category') }}</th><th>{{ t('financialUi.description') }}</th><th>{{ t('financialUi.amount') }}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.spent_on}}</td><td><span v-if="r.voided_at">{{ t('financialUi.expenses.voidedReason',{reason:r.void_reason}) }}</span><button v-else class="btn small-btn danger" :disabled="saving" @click="voidExpense(r)">{{ t('financialUi.void') }}</button></td><td><span class="badge">{{r.category}}</span></td><td><strong>{{r.description}}</strong></td><td class="numeric">{{money(r.amount)}}</td></tr></tbody></table><div v-if="!error&&(loading||!rows.length)" class="empty"><Receipt :size="26"/>{{loading?t('financialUi.loading'):t('financialUi.expenses.noExpenses')}}</div></div></section><ModalBox :open="modal" :title="t('financialUi.expenses.newTitle')" @close="modal=false"><form @submit.prevent="save"><div class="form-grid"><label>{{ t('financialUi.category') }}<select v-model="form.category"><option value="کرایه">{{ t('financialUi.expenses.rent') }}</option><option value="برق و خدمات">{{ t('financialUi.expenses.utilities') }}</option><option value="لوازم دفتر">{{ t('financialUi.expenses.officeSupplies') }}</option><option value="چاپ دفتر">{{ t('financialUi.expenses.officePrinting') }}</option><option value="ترمیمات">{{ t('financialUi.expenses.repairs') }}</option><option value="دیگر">{{ t('financialUi.expenses.other') }}</option></select></label><label>{{ t('financialUi.date') }}<input v-model="form.spent_on" type="date" required/></label><label class="wide">{{ t('financialUi.expenses.description') }}<input v-model="form.description" required/></label><label class="wide">{{ t('financialUi.expenses.amountRupees') }}<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required/></label></div><p class="hint" style="margin-top:13px">{{ t('financialUi.expenses.chapterPrintingNote') }}</p><div class="form-footer"><button type="button" class="btn" @click="modal=false">{{ t('financialUi.cancel') }}</button><button class="btn primary" :disabled="saving">{{ t('financialUi.expenses.new') }}</button></div></form></ModalBox></div></template>
